-- SOL定例資料の計画レイヤー。論点・TODO・依存関係の正本は変更しない。
BEGIN;
CREATE TABLE public.project_gantt_roadmaps (
 project_id text PRIMARY KEY REFERENCES public.projects(project_id),
 definition jsonb NOT NULL CHECK (jsonb_typeof(definition) = 'object'),
 source_ref text NOT NULL,
 updated_at timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE public.project_gantt_roadmaps IS '会議資料の工程・計画期間とゴールツリー参照。実行TODOや進捗の複製ではない';
ALTER TABLE public.project_gantt_roadmaps ENABLE ROW LEVEL SECURITY;
CREATE POLICY project_gantt_roadmaps_read ON public.project_gantt_roadmaps FOR SELECT TO authenticated USING (public.amd_os_can_access_project(project_id));
CREATE POLICY project_gantt_roadmaps_service ON public.project_gantt_roadmaps FOR ALL TO service_role USING (true) WITH CHECK (true);
GRANT SELECT ON public.project_gantt_roadmaps TO authenticated;
GRANT ALL ON public.project_gantt_roadmaps TO service_role;
